import React from "react";
import {
  useCurrentFrame,
  useVideoConfig,
  AbsoluteFill,
  interpolate,
  spring,
} from '../remotionShim';
import { makeLoadFont } from '../googleFonts';
const loadBebasNeue = makeLoadFont('BebasNeue');

// Load Google Font at module level to guarantee it's ready before frame 0
const { fontFamily: bebasNeueFamily } = loadBebasNeue();



export type TikTokSportsProps = Record<string, any>;

const TikTokSports: React.FC<TikTokSportsProps> = ({
  backgroundColor = "#0a0a0a",
  transparentBackground = true,
  durationInSeconds = 10,
  title = "FITNESS GRIND",
  primaryColor = "#E5FE40", // Neon fitness yellow
  textColor = "#0a0a0a",
  staggerDelay = 8,
  sportsList = [
    { name: "Rugby", emoji: "🏉" },
    { name: "Running", emoji: "🏃‍♂️" },
    { name: "Boxing", emoji: "🥊" },
    { name: "CrossFit", emoji: "🏋️‍♀️" },
    { name: "Weights", emoji: "🏋️‍♂️" },
  ],
}) => {
  const frame = useCurrentFrame();
  const { fps, width, height } = useVideoConfig();

  // Handle transparency
  const bgColor = transparentBackground ? `${backgroundColor}00` : backgroundColor;

  // Global slow zoom-in for dynamic energy
  const globalScale = interpolate(
    frame,
    [0, durationInSeconds * fps],
    [0.95, 1.05],
    { extrapolateRight: "clamp" }
  );

  // Title Animation
  const titleFrame = frame - 5;
  const titleScale = spring({
    fps,
    frame: titleFrame,
    config: { damping: 12, stiffness: 150 },
  });
  const titleOpacity = interpolate(titleFrame, [0, 10], [0, 1], {
    extrapolateRight: "clamp",
    extrapolateLeft: "clamp",
  });

  return (
    <AbsoluteFill style={{ backgroundColor: bgColor }}>
      <div
        style={{
          flex: 1,
          display: "flex",
          flexDirection: "column",
          justifyContent: "center",
          alignItems: "center",
          fontFamily: bebasNeueFamily,
          transform: `scale(${globalScale})`,
          // Ensure content stays within safe zones
          paddingTop: height * 0.15,
          paddingBottom: height * 0.1,
        }}
      >
        {/* Title */}
        <h1
          style={{
            fontSize: width * 0.12,
            color: "#ffffff",
            textTransform: "uppercase",
            margin: 0,
            marginBottom: "60px",
            opacity: titleOpacity,
            transform: `scale(${titleScale}) skewX(-5deg)`,
            textShadow: `4px 4px 0px ${primaryColor}`,
            textAlign: "center",
            lineHeight: 1,
          }}
        >
          {title}
        </h1>

        {/* Sports List Stack */}
        <div
          style={{
            display: "flex",
            flexDirection: "column",
            gap: "35px",
            width: "80%",
            maxWidth: "800px",
          }}
        >
          {sportsList.map((sport, index) => {
            const itemDelay = 15 + index * staggerDelay;
            const itemFrame = frame - itemDelay;

            // Spring-loaded pop-in
            const itemScale = spring({
              fps,
              frame: itemFrame,
              config: { damping: 10, mass: 0.8, stiffness: 120 },
            });

            // Slide in from the left slightly
            const translateX = interpolate(
              itemFrame,
              [0, 15],
              [-100, 0],
              { extrapolateRight: "clamp", extrapolateLeft: "clamp" }
            );

            // Alternate rotation for chaotic energy
            const rotation = index % 2 === 0 ? -2 : 2;

            return (
              <div
                key={`${sport.name}-${index}`}
                style={{
                  display: "flex",
                  flexDirection: "row",
                  alignItems: "center",
                  justifyContent: "center",
                  backgroundColor: primaryColor,
                  color: textColor,
                  padding: "20px 40px",
                  borderRadius: "24px",
                  transform: `scale(${itemScale}) translateX(${translateX}px) rotate(${rotation}deg)`,
                  boxShadow: "0 20px 40px rgba(0, 0, 0, 0.3)",
                  border: `4px solid ${textColor}`,
                }}
              >
                <span
                  style={{
                    fontSize: "80px",
                    marginRight: "30px",
                    fontFamily: '"Apple Color Emoji", "Segoe UI Emoji", "Noto Color Emoji", sans-serif',
                    lineHeight: 1,
                    filter: "drop-shadow(0px 10px 10px rgba(0,0,0,0.2))",
                  }}
                >
                  {sport.emoji}
                </span>
                <span
                  style={{
                    fontSize: "90px",
                    letterSpacing: "4px",
                    lineHeight: 1,
                    textTransform: "uppercase",
                  }}
                >
                  {sport.name}
                </span>
              </div>
            );
          })}
        </div>
      </div>
    </AbsoluteFill>
  );
};

export default TikTokSports;